/**
 * frontend/src/pages/Login.jsx - NOUVEAU FICHIER
 * Page de connexion
 */

import React, { useState } from 'react';
import authService from '../auth_service';

const COLORS = {
  primary: '#4F46E5',
  danger: '#EF4444',
  success: '#10B981',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  background: '#F8FAFC'
};

const Login = ({ onLoginSuccess }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [isRegister, setIsRegister] = useState(false);
  const [registerData, setRegisterData] = useState({
    username: '',
    email: '',
    password: '',
    passwordConfirm: '',
    firstName: ''
  });

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const result = await authService.login(username, password);

    if (result.success) {
      onLoginSuccess(result.user);
    } else {
      setError(result.error);
    }

    setLoading(false);
  };

  const handleRegister = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    if (registerData.password !== registerData.passwordConfirm) {
      setError('Les mots de passe ne correspondent pas');
      setLoading(false);
      return;
    }

    const result = await authService.register(
      registerData.username,
      registerData.email,
      registerData.password,
      registerData.passwordConfirm,
      registerData.firstName
    );

    if (result.success) {
      onLoginSuccess(result.user);
    } else {
      setError(result.error);
    }

    setLoading(false);
  };

  return (
    <div style={styles.container}>
      <div style={styles.background} />

      <div style={styles.formContainer}>
        <div style={styles.card}>
          {/* Logo */}
          <div style={styles.logo}>
            <div style={styles.logoIcon}>Σ</div>
            <h1 style={styles.logoText}>Attendance OS</h1>
          </div>

          {/* Tabs */}
          <div style={styles.tabs}>
            <button
              style={{
                ...styles.tab,
                borderBottom: !isRegister ? `2px solid ${COLORS.primary}` : 'none',
                color: !isRegister ? COLORS.primary : COLORS.textMuted
              }}
              onClick={() => setIsRegister(false)}
            >
              Connexion
            </button>
            <button
              style={{
                ...styles.tab,
                borderBottom: isRegister ? `2px solid ${COLORS.primary}` : 'none',
                color: isRegister ? COLORS.primary : COLORS.textMuted
              }}
              onClick={() => setIsRegister(true)}
            >
              Inscription
            </button>
          </div>

          {/* Error Message */}
          {error && (
            <div style={styles.errorBox}>
              <span style={styles.errorIcon}>⚠️</span>
              <span>{error}</span>
            </div>
          )}

          {/* Login Form */}
          {!isRegister ? (
            <form onSubmit={handleLogin} style={styles.form}>
              <div style={styles.formGroup}>
                <label style={styles.label}>Nom d'utilisateur</label>
                <input
                  type="text"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder="Entrez votre nom d'utilisateur"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Mot de passe</label>
                <input
                  type="password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Entrez votre mot de passe"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <button
                type="submit"
                style={{
                  ...styles.submitBtn,
                  opacity: loading ? 0.6 : 1,
                  cursor: loading ? 'not-allowed' : 'pointer'
                }}
                disabled={loading}
              >
                {loading ? '⏳ Connexion...' : '🚀 Se connecter'}
              </button>
            </form>
          ) : (
            /* Register Form */
            <form onSubmit={handleRegister} style={styles.form}>
              <div style={styles.formGroup}>
                <label style={styles.label}>Nom d'utilisateur</label>
                <input
                  type="text"
                  value={registerData.username}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, username: e.target.value })
                  }
                  placeholder="Choisissez un nom d'utilisateur"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Prénom</label>
                <input
                  type="text"
                  value={registerData.firstName}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, firstName: e.target.value })
                  }
                  placeholder="Votre prénom"
                  style={styles.input}
                  disabled={loading}
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Email</label>
                <input
                  type="email"
                  value={registerData.email}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, email: e.target.value })
                  }
                  placeholder="votre@email.com"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Mot de passe</label>
                <input
                  type="password"
                  value={registerData.password}
                  onChange={(e) =>
                    setRegisterData({ ...registerData, password: e.target.value })
                  }
                  placeholder="Min. 8 caractères"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <div style={styles.formGroup}>
                <label style={styles.label}>Confirmer le mot de passe</label>
                <input
                  type="password"
                  value={registerData.passwordConfirm}
                  onChange={(e) =>
                    setRegisterData({
                      ...registerData,
                      passwordConfirm: e.target.value
                    })
                  }
                  placeholder="Répétez le mot de passe"
                  style={styles.input}
                  disabled={loading}
                  required
                />
              </div>

              <button
                type="submit"
                style={{
                  ...styles.submitBtn,
                  opacity: loading ? 0.6 : 1,
                  cursor: loading ? 'not-allowed' : 'pointer'
                }}
                disabled={loading}
              >
                {loading ? '⏳ Inscription...' : '✨ S\'inscrire'}
              </button>
            </form>
          )}

          {/* Footer */}
          <p style={styles.footer}>
            {isRegister
              ? 'Vous avez déjà un compte? '
              : 'Pas de compte? '}
            <button
              style={styles.linkBtn}
              onClick={() => {
                setIsRegister(!isRegister);
                setError(null);
              }}
            >
              {isRegister ? 'Connectez-vous' : 'Inscrivez-vous'}
            </button>
          </p>
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    backgroundColor: COLORS.background,
    position: 'relative',
    overflow: 'hidden'
  },
  background: {
    position: 'absolute',
